        intent_str = (
            f"USER INTENT:\n"
            f"Action: {intent.action}\n"
            f"Target: {intent.target}\n"
            f"Parameters: {intent.parameters}\n"
            f'Original command: "{intent.raw_command}"\n'
            f"Complexity: {intent.complexity}\n"
            f"Domain: {intent.domain}"
        )

        context_str = self._format_context(context)

        history_str = ""
        if sequence.steps:
            history_str = "HISTORY OF ACTIONS:\n"
            for i, step in enumerate(sequence.steps):
                history_str += f"\n--- Step {i+1} ---\n"
                history_str += f"Description: {step.description}\n"
                history_str += f"Action: {step.parameters.get('action')}({step.parameters})\n"
                history_str += f"Status: {step.status.value}\n"
                # Context integration for results can be added here if available in context

        return f"{intent_str}\n\n{context_str}\n\n{history_str}\n\nDecide the next action."

    def _format_context(self, context: ExecutionContext) -> str:
        lines = []
        if context.current_window:
            lines.append(f"FOREGROUND WINDOW: {context.current_window.title} (process: {context.current_window.process_name})")

        if not lines:
            return "CONTEXT: (no special context available)"
        return "CONTEXT:\n" + "\n".join(lines)

