        return IntentStep(
            step_id=len(sequence.steps) + 1,
            description=response.get("description", ""),
            expected_output="Step success",
            parameters={"action": action, **response.get("parameters", {})},
            status=StepExecutionStatus.PENDING
        )

    def evaluate(self, sequence: IntentSequence, context: ExecutionContext) -> bool:
        # 1. Check if all steps in sequence are COMPLETED
        # 2. Ask GoalVerifier (future) if intent is truly satisfied
        return sequence.is_complete()

