UTIL_HANDLERS = [WaitHandler]
def get_util_handers()->list:
    return [handler() for handler in UTIL_HANDLERS]

__all__ = [
    'WaitHandler',
    'UTIL_HANDLERS',
    'get_util_handers'
]

