from ..context import ExecutionContext

DEFAULT_WAIT_SECONDS = 1.0
MAX_WAIT_SECONDS = 30.0
DEFAULT_FIND_TIMEOUT = 5.0
FIND_RETRY_INTERVAL = 0.5

