                        return ActionResult(
                            success=True,
                            data = {
                                'element_label':visual_element.label,
                                'element_type':visual_element.element_type,
                                'bounding_box':visual_element.bounding_box,
                                'center':visual_element.center,
                                'confidence':visual_element.confidence,
                                'cached_as':cache_as,
                                'source':'visual',
                                'attempt':attempt
                            },
                            method_used='visual'
