        except:
            return None

    def verify(self, params:Dict[str,Any], context: ExecutionContext, result: ActionResult)->VerifyResult:
        if not result.success:
            return VerifyResult(
                verified=False,
                confidence=0.0,
                reason = 'Element was not found'
