_tool_embeddings: dict = {}


def _embed_tools() -> None:
    """Lazy init — embeds all tool descriptions once and caches them."""
    global _tool_embeddings
    if _tool_embeddings:
        return
    try:
        from ...memory.graph.embedder import embed
        print("[PromptBuilder] Embedding tool descriptions...")
        for name, desc in TOOL_REGISTRY.items():
            _tool_embeddings[name] = embed(f"{name}: {desc}")
        print(f"[PromptBuilder] {len(_tool_embeddings)} tool embeddings ready.")
    except Exception as e:
        print(f"[PromptBuilder] Failed to embed tools: {e}")


def _retrieve_tools(step_description: str, domain: str, top_k: int = 5) -> list:
    """
    Embed step_description and return the top_k most relevant tool names
    by cosine similarity, with the domain anchor always at position 0.
    """
    _embed_tools()

    if not _tool_embeddings:
        # Fallback: return anchor + a few defaults if embedding failed
        anchor = DOMAIN_ANCHOR.get(domain, "wait")
        return [anchor]

    try:
        from ...memory.graph.embedder import embed
        query_emb = np.array(embed(step_description))

        scores = {}
        for name, emb in _tool_embeddings.items():
            b = np.array(emb)
            scores[name] = float(
                np.dot(query_emb, b) /
                (np.linalg.norm(query_emb) * np.linalg.norm(b) + 1e-9)
            )

        ranked = sorted(scores, key=scores.get, reverse=True)[:top_k]

        # Enforce domain anchor at front
        anchor = DOMAIN_ANCHOR.get(domain)

from ...core.task import IntentStep, IntentSequence
from ...core.config import ActionResult
from ...action.context import ExecutionContext

def verify_step(step: IntentStep, result: ActionResult, context: ExecutionContext) -> tuple[bool, str]:
    """
    Step 1: If result.success is False, return (False, result.error).
    Step 2: Check domain-specific verification signals.
    Step 3: If no domain-specific check applies, return (True, "Success")
    """
    if not result.success:
        return (False, result.error or "Unknown error")

    domain = step.domain

    if domain == "app":
        # check if current_window is not None
        if not context.current_window:
            return (False, "No active window found after app operation")

    elif domain == "window":
        if step.target:
            fg = context.get_variable('current_window_title', '')
            if step.target.lower() not in fg.lower():
                return (False, f"Foreground window '{fg}' does not match target '{step.target}'")

    elif domain == "web":
      url = context.get_variable("current_url", "")
      if step.target and url:
          # Normalize both: strip protocol, www., trailing slash
          def _norm(u):
              u = u.lower().split("?")[0].split("#")[0]
              for prefix in ("https://www.", "http://www.", "https://", "http://"):
                  if u.startswith(prefix):
                      u = u[len(prefix):]
              return u.rstrip("/")

          if _norm(step.target) not in _norm(url) and _norm(url) not in _norm(step.target):
              return (False, f"Target '{step.target}' not found in current URL '{url}'")

    elif domain == "file":
        import os
        path = step.parameters.get("path") or step.target
        if path and not os.path.exists(path):
            return (False, f"Expected path '{path}' does not exist")

    return (True, "Success")

class GoalVerifier:
    def __init__(self):
        pass

    def verify(self, sequence: IntentSequence, context: ExecutionContext) -> bool:
        """Verify if the ultimate goal of the sequence has been achieved."""
        return sequence.is_complete()

